use verus::prelude::*;

verus! {

    /// Given a finite vector of 8‐bit signed integers `s`, produce a new vector `rev`
    /// containing the elements of `s` in reverse order.
    /// 
    /// The result `rev` satisfies:
    ///   1. `rev` has the same length as `s`.
    ///   2. For every valid index `k` in `0..s.len()`, 
    ///      `rev[k] == s[s.len() - 1 - k]`.
    #[verifier(publish)]
    fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
        ensures rev@.len() == s@.len()
        ensures forall |k: nat| k < s@.len() ==> rev@[k] == s@[s@.len() - 1 - k]
    {
        // We'll build up `rev` by popping elements off the end of `s`
        // (conceptually) one by one.
        let mut rev: Vec<i8> = Vec::new();
        // `i` will range from `s.len()` down to `0`.
        let mut i: usize = s.len();
        // Capture `s.len()` in `n` for use in invariants.
        let n: usize = s.len();
        // Relate the runtime length to the spec‐level length.
        assert(n == s@.len());

        // Loop until we've processed all `n` elements.
        while i > 0 {
            // 0 <= i <= n
            invariant i <= n;
            // At each step, we've already pushed `n - i` elements into `rev`.
            // Equivalently, rev@.len() + i == n.
            invariant rev@.len() + i == n;
            // And those `rev` elements are exactly the last `n - i` elements
            // of `s`, in reverse order:
            //
            //    for all 0 <= j < rev@.len():
            //       rev[j] == s[n-1-j]
            invariant
                forall |j: nat| j < rev@.len() ==>
                    rev@[j] == s@[n - 1 - j];
            decreases i;

            // Peel off one more element from the end:
            i -= 1;
            rev.push(s[i]);
        }

        rev
    }
}